<?php foreach($schema as $question):$qid=$question['id'];?><label for="<?= e($qid) ?>"><?= e($question['label']) ?><?= $question['required']?' (required)':'' ?></label><?php if($question['type']==='textarea'):?><textarea id="<?= e($qid) ?>" name="<?= e($qid) ?>" rows="4" maxlength="4000"<?= $question['required']?' required':'' ?><?= !empty($preview)?' disabled':'' ?>><?= e(field($qid)) ?></textarea><?php elseif($question['type']==='select'):?><select id="<?= e($qid) ?>" name="<?= e($qid) ?>"<?= $question['required']?' required':'' ?><?= !empty($preview)?' disabled':'' ?>><option value="">Choose an option</option><?php foreach($question['options'] as $choice):?><option value="<?= e($choice) ?>"<?= field($qid)===$choice?' selected':'' ?>><?= e($choice) ?></option><?php endforeach;?></select><?php else:?><input id="<?= e($qid) ?>" name="<?= e($qid) ?>" type="<?= e(match($question['type']){'checkbox'=>'checkbox','url'=>'url','file'=>'file',default=>'text'}) ?>"<?= $question['type']==='checkbox'?' value="1"':($question['type']==='file'?' accept=".jpg,.jpeg,.png,.webp,.pdf"':' maxlength="1000" value="'.e(field($qid)).'"') ?><?= $question['required']?' required':'' ?><?= !empty($preview)?' disabled':'' ?>><?php endif;?><?php if($question['type']==='file'):?><p class="field-help">JPG, PNG, WebP or PDF only; up to 2 MiB. Use external links for large videos. Reselect files after any validation error.</p><?php endif;?><?php endforeach;?>
